-- Seed: user_db (4 Tiered Admins + 8 Enterprise Division Leads/Officers).
-- Idempotent. Run: psql -d user_db -f this
\set ON_ERROR_STOP on
\if :{?actor} \else \set actor '00000000-0000-0000-0000-000000000001' \endif

-- 12 Starter Users
ON CONFLICT (username) DO NOTHING;

-- Org/Division & Role Assignments (referencing deterministic org_db & security_db UUIDs)
ON CONFLICT (user_id, organization_ref_id, role_id) DO NOTHING;
